INSERT INTO activity (id, title, category_id, cover_url, summary, content, location, start_time, end_time, signup_deadline, capacity, signed_count, status, organizer_id, audit_remark, checkin_code, code_expire_time, need_audit, create_time, update_time) VALUES
(1, '2026 年校园十佳歌手大赛', 1, NULL, '一年一度的校园音乐盛事，20 位选手同台竞演', '比赛分为初赛、复赛、决赛三个阶段，决赛现场设专业评委与大众评审。观众报名后可入场观赛，请提前 15 分钟入场就座。', '大学生活动中心礼堂', '2026-12-05 19:00:00', '2026-12-05 21:30:00', '2026-12-03 18:00:00', 200, 37, 2, 2, NULL, NULL, NULL, 0, '2026-11-01 10:00:00', '2026-11-10 15:30:00'),
(2, '冬季篮球联赛（院系组）', 2, NULL, '八个学院组队参赛，为期两周的循环赛', '以学院为单位报名，每队 12 人。比赛采用四节制，每节 10 分钟。参赛队员需自行购买意外险。', '东区室外篮球场', '2026-12-12 15:00:00', '2026-12-12 18:00:00', '2026-12-10 12:00:00', 120, 58, 2, 2, NULL, NULL, NULL, 0, '2026-11-02 14:20:00', '2026-11-12 09:00:00'),
(3, '人工智能与校园生活专题讲座', 3, NULL, '计算机学院教授主讲，聊聊大模型在日常学习中的应用', '讲座围绕大模型的基本原理、常见应用场景和学术诚信边界展开，现场设提问环节，可携带笔记本入场。', '图书馆报告厅', '2026-11-28 14:00:00', '2026-11-28 16:00:00', '2026-11-27 20:00:00', 80, 61, 2, 2, NULL, NULL, NULL, 0, '2026-11-05 11:00:00', '2026-11-15 16:40:00'),
(4, '图书馆志愿整理服务', 4, NULL, '整理书架、录入新书，计入志愿服务时长', '每周一次，每次 3 小时，可累计志愿时长。请穿着便于活动的衣物，馆内禁止饮食。', '图书馆三楼社科阅览室', '2026-11-22 09:00:00', '2026-11-22 12:00:00', '2026-11-21 18:00:00', 30, 12, 2, 2, NULL, NULL, NULL, 0, '2026-11-06 09:10:00', '2026-11-16 10:00:00'),
(5, '2026 国庆文艺汇演', 1, NULL, '师生同台，共庆国庆', '汇演包含合唱、舞蹈、器乐、朗诵等 12 个节目，总时长约 2 小时。', '大学生活动中心礼堂', '2026-10-01 19:00:00', '2026-10-01 21:00:00', '2026-09-28 18:00:00', 300, 46, 5, 2, NULL, NULL, NULL, 0, '2026-08-20 10:00:00', '2026-10-02 08:00:00'),
(6, '社团招新嘉年华', 5, NULL, '二十余个社团集中摆摊，现场可报名加入', '各社团在中心广场设展位，现场展示社团成果，学生可自由咨询并现场登记。', '大学生活动中心前广场', '2026-12-20 09:00:00', '2026-12-20 17:00:00', '2026-12-18 18:00:00', 500, 0, 1, 2, NULL, NULL, NULL, 0, '2026-11-16 15:30:00', '2026-11-16 15:30:00'),
(7, '期末复习经验分享会', 3, NULL, '邀请高年级同学分享复习方法', '分享会内容包括复习计划制定、专业课资料整理、应试心态调整。', '图书馆报告厅', '2026-11-25 19:00:00', '2026-11-25 21:00:00', '2026-11-24 18:00:00', 60, 0, 3, 2, '活动时间与图书馆闭馆时间冲突，请调整后重新提交', NULL, NULL, 0, '2026-11-15 09:00:00', '2026-11-17 10:20:00'),
(8, '新生心理健康与适应讲座', 3, NULL, '心理咨询中心老师主讲，聊聊入学后的情绪与压力', '讲座内容包括常见心理困扰识别、简单放松训练、校内心理咨询预约方式，现场可匿名提问。', '大学生活动中心报告厅', '2026-11-14 14:00:00', '2026-11-14 16:00:00', '2026-11-13 18:00:00', 100, 18, 5, 2, NULL, NULL, NULL, 0, '2026-11-08 10:00:00', '2026-11-14 16:05:00');
