INSERT INTO activity_review (id, activity_id, user_id, score, content, anonymous, create_time) VALUES
(1, 5, 3, 5, '舞台效果比去年好很多，节目衔接也很顺畅，看得出排练了很久。', 0, '2026-10-02 10:20:00'),
(2, 5, 4, 4, '整体不错，就是中途音响有点小问题，后半场人太多有点挤。', 0, '2026-10-02 11:05:00'),
(3, 5, 101, 5, '合唱节目很震撼，希望能多办几场。', 1, '2026-10-02 12:10:00'),
(4, 5, 105, 3, '入场排队时间有点长，其他都还行。', 0, '2026-10-02 13:30:00'),
(5, 8, 144, 5, '老师讲得很实在，关于情绪波动的解释让我踏实了不少。', 0, '2026-11-14 20:10:00'),
(6, 8, 145, 4, '内容不错，就是时间有点紧，放松训练只做了一轮。', 1, '2026-11-14 21:05:00'),
(7, 8, 146, 4, '希望以后能多安排一些类似的讲座。', 0, '2026-11-15 09:20:00');
INSERT INTO notice (id, user_id, title, content, notice_type, is_read, create_time) VALUES
(1, 3, '报名成功', '你已成功报名「2026 年校园十佳歌手大赛」，请于 12 月 5 日 18:45 前入场。', 'ACTIVITY', 0, '2026-11-12 20:15:10'),
(2, 3, '活动评分邀请', '「2026 国庆文艺汇演」已结束，欢迎为活动打分并留下你的评价。', 'SYSTEM', 1, '2026-10-02 08:00:00'),
(3, 4, '爽约提醒', '你报名的「2026 国庆文艺汇演」未签到，已记录一次爽约。累计 2 次将限制报名 30 天。', 'SYSTEM', 0, '2026-10-02 08:00:05'),
(4, 2, '活动审核结果', '你提交的「期末复习经验分享会」未通过审核，原因：活动时间与图书馆闭馆时间冲突。', 'AUDIT', 0, '2026-11-17 10:20:30');
INSERT INTO sys_notice (id, title, content, publisher_id, status, create_time, update_time) VALUES
(1, '关于开展 2026 年冬季校园文化节的通知', '各学院、各学生组织：冬季校园文化节将于 12 月举办，包含文艺演出、体育竞技、志愿服务等系列活动，欢迎踊跃报名参与。', 1, 1, '2026-11-01 09:00:00', '2026-11-01 09:00:00');
